using System;using System.Linq;using UnityEngine;using UnityEditor;
public static class ProbeHarborVideoState{public static object Main(){var story=UnityEngine.Object.FindFirstObjectByType<OpeningStoryUI>();var field=typeof(OpeningStoryUI).GetField("seeking",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);return "page="+story.CurrentPage+", time="+story.video.time+", prepared="+story.video.isPrepared+", frame="+story.video.frame+", playing="+story.video.isPlaying+", enabled="+story.video.enabled+", active="+story.video.gameObject.activeInHierarchy+", speed="+story.video.playbackSpeed+", seeking="+field.GetValue(story)+", previous target="+story.previousButton.onClick.GetPersistentMethodName(0)+", interactable="+story.previousButton.interactable+", background="+Application.runInBackground+", scale="+Time.timeScale;}}
